'use strict';
const sources={...editorialSources,...researchSources};
const nodes=researchNodes;
const stages=researchStages;
const stageNames=['定义泡沫','投入与现金','加入反证','工作假设'];
const $=s=>document.querySelector(s);let selected='judgment',view='map',stage=3,toastTimer;
function sourceButtons(ids){return ids.map(id=>`<button class="source-button" data-open-source="${id}"><small>${sources[id].kind}</small>${sources[id].title}</button>`).join('');}
function selectNode(id){if(!Object.hasOwn(nodes,id))throw new Error('未知观点');selected=id;const n=nodes[id];$('#detail').innerHTML=`<span class="detail-number">${n.index}</span><h2>${n.title}</h2><span class="label ${id==='judgment'?'green-label':''}">${n.type}</span><p>${n.text}</p><h3>关联材料 · ${n.sources.length} 份</h3>${sourceButtons(n.sources)}<p class="detail-question">${n.question}</p>`;document.querySelectorAll('[data-node]').forEach(el=>{el.classList.toggle('selected',el.dataset.node===id);el.setAttribute('aria-pressed',String(el.dataset.node===id));});return {id,title:n.title,type:n.type,sources:n.sources};}
function setView(name){if(!['map','evidence','timeline','capex','library'].includes(name))throw new Error('未知视图');view=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==name+'-view');document.querySelectorAll('.tab').forEach(el=>{el.classList.toggle('active',el.dataset.view===name);el.setAttribute('aria-selected',String(el.dataset.view===name));el.tabIndex=el.dataset.view===name?0:-1;});$('#viewHint').textContent={map:'点击节点，沿着证据继续探索',evidence:'让反向证据也进入判断',timeline:'拖动时间轴，回看思考的变化',capex:'现金、租赁与财期分开看',library:'7 份公开材料 · 5 份编辑分析'}[name];return {view};}
function openSource(id){if(!Object.hasOwn(sources,id))throw new Error('未知材料');const s=sources[id];$('#sourceContent').innerHTML=`<h2>${s.title}</h2><p class="source-meta">${s.meta||s.kind} · ${s.url?'中文整理 · 非原文逐字引述':'编辑分析 · 非公司披露事实'}</p><div class="source-body">${s.body}</div>${s.url?`<a class="original-link" href="${s.url}" target="_blank" rel="noopener noreferrer">阅读原文</a><p class="source-original-title">${s.originalTitle}</p>`:""}<p class="source-caveat">证据边界：${s.boundary}</p><p class="source-relation">保留材料的限制条件，是追溯判断的一部分。</p>`;if(!$('#sourceDialog').open)$('#sourceDialog').showModal();return {id,title:s.title,kind:s.kind,body:s.body,boundary:s.boundary};}
function setStage(index){if(!Number.isInteger(index)||index<0||index>=stages.length)throw new Error('未知研究阶段');stage=index;$('#stageRange').value=index;document.querySelectorAll('[data-stage]').forEach(el=>el.classList.toggle('active',Number(el.dataset.stage)===index));const s=stages[index];$('#stageContent').innerHTML=`<article class="stage-content"><div class="stage-index">0${index+1}</div><div><p class="eyebrow">${stageNames[index]} / 示例论证路径</p><h3>${s.title}</h3><p>${s.text}</p><div class="stage-change"><small>这一阶段改变了什么</small><p>${s.change}</p></div><div class="stage-source">${sourceButtons(s.sources)}</div></div></article>`;return {stage:index,title:s.title};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function saveConclusion(){const text=$('#conclusionText').value.trim();if(!text){toast('先写下一段判断，再保存。');return false;}try{localStorage.setItem('jianwei.ai-bubble.conclusion.v1',text);$('#saveStatus').textContent='已保存到当前浏览器 · 不会同步到其他设备';toast('判断已保存');return true;}catch{toast('当前浏览器无法保存，可导出研究结论。');return false;}}
function exportMarkdown(){const conclusion=$('#conclusionText').value.trim();const text=`# 见微 · AI 泡沫与资本开支\n\n> 交互原型。包含 7 份公开披露或机构观点与 5 份编辑分析；资料核对日期为 2026-10-08；未接入个人资料或实时 AI。\n\n## 研究问题\n这一轮 AI 发展，是不是泡沫？\n\n## 当前判断\n${conclusion||'尚未填写'}\n\n## 观点与证据边界\n${Object.values(nodes).map(n=>`### ${n.title}\n类型：${n.type}\n\n${n.text}\n\n关联材料：${n.sources.map(id=>sources[id].title).join('、')}\n\n追问：${n.question}\n`).join('\n')}\n## 资料与出处\n${Object.values(sources).map(s=>`### ${s.title}\n${s.meta||s.kind}\n${s.url?"原文："+s.url:"编辑分析，非公司披露"}\n\n${s.body}\n\n证据边界：${s.boundary}\n`).join('\n')}\n## 判断变化\n${stages.map((s,i)=>`### 阶段 ${i+1}：${s.title}\n${s.text}\n\n${s.change}\n`).join('\n')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='见微-AI泡沫与CapEx.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出 Markdown 研究记录');}
const evidence=researchEvidence;
for(const key of ['support','challenge'])$('#'+key+'-list').innerHTML=evidence[key].map(e=>`<article class="evidence-card"><p class="eyebrow">${e.tag}</p><h4>${e.title}</h4><p>${e.text}</p><button class="text-button" data-open-source="${e.source}">阅读关联材料</button></article>`).join('');
function renderLibrary(){
 const groups=[{title:'公开披露与机构观点',note:'公司披露事实与机构历史观点分开标注，日期和财期见材料详情。',ids:Object.keys(researchSources)},{title:'编辑分析与观察框架',note:'以下是编辑整理的推断、情景和观察问题，不代表已确认事实。',ids:['s1','s2','s3','s4','s5']}];
 $('#libraryContent').innerHTML=groups.map(g=>`<div class="library-group"><h3>${g.title}<small>${g.ids.length} 份</small></h3><p class="library-note">${g.note}</p><div class="library-grid">${g.ids.map((id,i)=>{const s=sources[id];return `<article class="library-card"><span class="eyebrow">${s.meta||s.kind}</span><h4>${s.title}</h4><p>${s.summary||s.body.split('\n')[0]}</p><div class="library-actions"><button class="text-button" data-open-source="${id}">阅读整理</button>${s.url?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">原文</a>`:'<span>编辑分析</span>'}</div></article>`;}).join('')}</div></div>`).join('');
}
renderLibrary();
document.addEventListener('click' ,e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.node)selectNode(b.dataset.node);if(b.dataset.view)setView(b.dataset.view);if(b.dataset.openSource)openSource(b.dataset.openSource);if(b.dataset.stage!==undefined)setStage(Number(b.dataset.stage));});
$('#stageRange').addEventListener('input',e=>setStage(Number(e.target.value)));$('#closeSource').addEventListener('click',()=>$('#sourceDialog').close());$('#sourceDialog').addEventListener('click',e=>{if(e.target===$('#sourceDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#saveConclusion').addEventListener('click',saveConclusion);$('#export').addEventListener('click',exportMarkdown);$('#conclusionText').addEventListener('input',()=>$('#saveStatus').textContent='有未保存的修改');
try{const saved=localStorage.getItem('jianwei.ai-bubble.conclusion.v1');if(saved){$('#conclusionText').value=saved;$('#saveStatus').textContent='已恢复当前浏览器保存的判断';}}catch{}
selectNode('judgment');setStage(3);
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_research_state',description:'读取当前研究视图、所选观点、阶段与编辑中的结论。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view,selected,stage,conclusion:$('#conclusionText').value,prototype:true,publicSourceCount:7,asOf:"2026-10-08"})},{name:'navigate_research_view',description:'切换到观点地图、证据对照或认知时间轴。',inputSchema:{type:'object',properties:{view:{type:'string',enum:['map','evidence','timeline','capex','library']}},required:['view'],additionalProperties:false},execute:input=>setView(input.view)},{name:'select_research_node',description:'选择一个观点并在详情面板显示其材料与证据边界。',inputSchema:{type:'object',properties:{id:{type:'string',enum:Object.keys(nodes)}},required:['id'],additionalProperties:false},execute:input=>{if(!input||!Object.hasOwn(nodes,input.id))throw new Error('未知观点');setView('map');return selectNode(input.id);}},{name:'navigate_research_stage',description:'选择并显示演示研究历程中的阶段。',inputSchema:{type:'object',properties:{stage:{type:'integer',minimum:0,maximum:3}},required:['stage'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.stage)||input.stage<0||input.stage>=stages.length)throw new Error('未知阶段');setView('timeline');return setStage(input.stage);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}

$('.tabs').addEventListener('keydown',event=>{
 if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
 const tabs=Array.from(document.querySelectorAll('.tab'));const current=tabs.indexOf(event.target);if(current<0)return;
 event.preventDefault();let next=current;
 if(event.key==='ArrowRight')next=(current+1)%tabs.length;
 if(event.key==='ArrowLeft')next=(current-1+tabs.length)%tabs.length;
 if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;
 setView(tabs[next].dataset.view);tabs[next].focus();
});
